let stage=0,days=0,role="Guardian";const p=document.querySelector("#panel"),l=document.querySelector("#log");document.querySelectorAll(".go").forEach(b=>b.onclick=()=>document.querySelector("#forge").scrollIntoView());function render(){if(stage===1)p.innerHTML='<small>ANTI-SNAPSHOT PROOF</small><h3>Commitment takes time.</h3><p>Hold 10,000 TOTEM for seven days.</p><b id="days">'+days+' / 7 DAYS</b><br><br><button class="lime" id="day">Simulate next day +24h</button>';if(stage===2)p.innerHTML='<small>SIGNED QUEST RECEIPT</small><h3>Make the meme travel.</h3><p>Issue a one-use proof bound to wallet, culture, action, nonce, and expiry.</p><button class="lime" id="quest">Verify quest ↗</button>';if(stage===3)p.innerHTML='<small>BRANCHING EVOLUTION</small><h3>Choose your branch.</h3><button data-r="Guardian">◇ Guardian</button> <button data-r="Maker">✦ Maker</button><br><br><button class="lime" id="mint">Mint identity ◎</button>';if(stage===4)p.innerHTML='<small>IDENTITY ACTIVE</small><h3>'+role+' #0042</h3><p>Your first segment is carved.</p><div style="font-size:80px;color:#b7ff37">⬟◆⬢</div>';bind()}function bind(){let d=document.querySelector("#day");if(d)d.onclick=()=>{days++;l.textContent+="\\n[checkpoint] day "+days+" valid";document.querySelector("#days").textContent=days+" / 7 DAYS";if(days===7){stage=2;render()}};let q=document.querySelector("#quest");if(q)q.onclick=()=>{l.textContent+="\\n[receipt] nonce consumed";stage=3;render()};document.querySelectorAll("[data-r]").forEach(b=>b.onclick=()=>role=b.dataset.r);let m=document.querySelector("#mint");if(m)m.onclick=()=>{l.textContent+="\\n[mint] totem #0042 created";stage=4;render()}}document.querySelector("#next").onclick=()=>{stage=1;l.textContent+="\\n[token] totem.demo.near verified";render()};
